insert into public.exercises
  (id, name, summary, steps, kind, fits, topics, min_age, min_players, duration, equipment, contact, video_url, status)
values
  ('ball-tag', '{"es":"Mancha con pelota","en":"Ball tag"}'::jsonb, '{"es":"Mancha clásica donde el que lleva la pelota está a salvo. Activa y obliga a pasar rápido.","en":"Classic tag where the ball carrier is safe. Gets everyone moving and passing fast."}'::jsonb, '[{"es":"Marcar un cuadrado de 20 x 20 m con conos.","en":"Mark a 20 x 20 m square with cones."},{"es":"Uno o dos \"manchas\" persiguen; quien tiene la pelota no puede ser tocado.","en":"One or two taggers chase; whoever holds the ball cannot be tagged."},{"es":"Los demás se pasan la pelota para salvar al compañero amenazado.","en":"The others pass to save the teammate under threat."}]'::jsonb, 'game', array['warmup']::text[], array['passing', 'evasion']::text[], 6, 6, 10, array['balls', 'cones']::text[], 'none', null, 'approved'),
  ('dynamic-mobility', '{"es":"Movilidad dinámica con pelota","en":"Dynamic mobility with ball"}'::jsonb, '{"es":"Desplazamientos y movilidad articular manejando la pelota.","en":"Movement patterns and joint mobility while handling the ball."}'::jsonb, '[{"es":"En parejas, a lo ancho de 15 m.","en":"In pairs, across 15 m."},{"es":"Trote, skipping, talones, desplazamiento lateral, pasándose la pelota.","en":"Jog, high knees, heel flicks, side steps, passing the ball."},{"es":"Terminar con dos piques cortos.","en":"Finish with two short sprints."}]'::jsonb, 'drill', array['warmup']::text[], array['passing']::text[], 6, 2, 8, array['balls']::text[], 'none', null, 'approved'),
  ('square-passing', '{"es":"Pases en cuadrado","en":"Square passing"}'::jsonb, '{"es":"Filas en las cuatro esquinas; se corre y se pasa en sentido horario y antihorario.","en":"Lines on four corners; run and pass clockwise and anticlockwise."}'::jsonb, '[{"es":"Cuadrado de 10 x 10 m con una fila en cada esquina.","en":"10 x 10 m square with a line on each corner."},{"es":"El primero corre hacia la esquina siguiente y pasa al que sale de ahí.","en":"The first player runs to the next corner and passes to whoever leaves from there."},{"es":"Cambiar de sentido para trabajar pase a ambas manos.","en":"Switch direction to work passing on both sides."}]'::jsonb, 'drill', array['warmup', 'technique']::text[], array['passing']::text[], 7, 8, 10, array['balls', 'cones']::text[], 'none', null, 'approved'),
  ('four-corners-game', '{"es":"Los cuatro rincones","en":"Four corners"}'::jsonb, '{"es":"Juego de reacción: el entrenador canta un rincón y todos corren a tocarlo con la pelota.","en":"Reaction game: the coach calls a corner and everyone races to touch it with a ball."}'::jsonb, '[{"es":"Cuadrado de 15 x 15 m, cada rincón con un color de cono.","en":"15 x 15 m square, each corner a different cone colour."},{"es":"Los jugadores trotan con pelota en el centro.","en":"Players jog with a ball in the middle."},{"es":"Al grito del color, corren a apoyar la pelota en ese rincón.","en":"When a colour is called, they run to ground the ball at that corner."}]'::jsonb, 'game', array['warmup']::text[], array['evasion']::text[], 6, 4, 8, array['balls', 'cones']::text[], 'none', null, 'approved'),
  ('running-lines-passing', '{"es":"Pase en línea en carrera","en":"Running line passing"}'::jsonb, '{"es":"Líneas de 4 que avanzan pasando la pelota lateralmente hasta el final.","en":"Lines of 4 moving forward and passing laterally to the end."}'::jsonb, '[{"es":"Grupos de 4 en línea, separados 3 a 5 m.","en":"Groups of 4 in a line, 3 to 5 m apart."},{"es":"Avanzar 30 m pasando hacia atrás y al costado.","en":"Move 30 m passing backwards and sideways."},{"es":"Volver pasando hacia el otro lado.","en":"Come back passing to the other side."}]'::jsonb, 'drill', array['technique']::text[], array['passing', 'attack']::text[], 7, 4, 12, array['balls', 'cones']::text[], 'none', null, 'approved'),
  ('two-vs-one', '{"es":"2 contra 1","en":"2 v 1"}'::jsonb, '{"es":"Dos atacantes contra un defensor en un canal: fijar y pasar.","en":"Two attackers against one defender in a channel: fix and pass."}'::jsonb, '[{"es":"Canal de 10 m de ancho por 15 m de largo.","en":"Channel 10 m wide by 15 m long."},{"es":"El portador ataca al defensor para fijarlo y pasa al compañero libre.","en":"The carrier runs at the defender to fix them, then passes to the free teammate."},{"es":"Defensa con toque a dos manos. Rotar roles.","en":"Defence with two-hand touch. Rotate roles."}]'::jsonb, 'drill', array['technique']::text[], array['attack', 'passing', 'evasion']::text[], 8, 3, 12, array['balls', 'cones']::text[], 'tag', null, 'approved'),
  ('kneeling-tackle', '{"es":"Tackle de rodillas","en":"Kneeling tackle"}'::jsonb, '{"es":"Técnica de tackle segura desde rodillas: cabeza al costado, hombro, abrazar.","en":"Safe tackle technique from the knees: head to the side, shoulder, wrap."}'::jsonb, '[{"es":"En parejas, ambos de rodillas sobre pasto blando.","en":"In pairs, both kneeling on soft grass."},{"es":"Mejilla contra la cadera del compañero, contacto con el hombro y abrazo.","en":"Cheek to partner’s hip, shoulder contact and wrap."},{"es":"Llevarlo al piso de costado, sin velocidad. Repetir por ambos lados.","en":"Take them to ground sideways, no speed. Repeat on both sides."}]'::jsonb, 'drill', array['technique']::text[], array['tackle', 'defense']::text[], 9, 2, 10, '{}'::text[], 'controlled', null, 'approved'),
  ('shield-tackle', '{"es":"Tackle contra escudo","en":"Shield tackle"}'::jsonb, '{"es":"Entrada al tackle caminando y luego trotando contra un escudo.","en":"Tackle entry walking, then jogging, into a shield."}'::jsonb, '[{"es":"Un jugador sostiene el escudo; el otro se acerca con pasos cortos.","en":"One player holds the shield; the other approaches with short steps."},{"es":"Bajar la cadera, cabeza al costado, contacto con el hombro y empujar con las piernas.","en":"Lower the hips, head to the side, shoulder contact and drive with the legs."},{"es":"Aumentar la velocidad sólo si la técnica es correcta.","en":"Increase speed only when technique is correct."}]'::jsonb, 'drill', array['technique']::text[], array['tackle', 'defense']::text[], 11, 2, 12, array['shields']::text[], 'controlled', null, 'approved'),
  ('go-to-ground', '{"es":"Caída y presentación de pelota","en":"Go to ground and present"}'::jsonb, '{"es":"Caer de forma segura al ser tackleado y presentar la pelota para el equipo.","en":"Fall safely when tackled and present the ball for your team."}'::jsonb, '[{"es":"Trotar con la pelota y, a la señal, caer de costado protegiendo la pelota.","en":"Jog with the ball and, on the call, fall sideways protecting it."},{"es":"Girar hacia el propio equipo y dejar la pelota atrás con brazos largos.","en":"Turn towards your team and place the ball back with long arms."},{"es":"Un compañero llega y levanta la pelota.","en":"A teammate arrives and picks up the ball."}]'::jsonb, 'drill', array['technique']::text[], array['ruck']::text[], 8, 2, 10, array['balls']::text[], 'none', null, 'approved'),
  ('ruck-clearout-shields', '{"es":"Limpieza de ruck con escudos","en":"Ruck clear-out with shields"}'::jsonb, '{"es":"Llegar al ruck y limpiar al defensor (escudo) con postura baja.","en":"Arrive at the ruck and clear the defender (shield) with a low body position."}'::jsonb, '[{"es":"Pelota en el piso, un jugador con escudo sobre ella.","en":"Ball on the ground, a player with a shield over it."},{"es":"Dos atacantes entran por la puerta, bajos, y empujan el escudo más allá de la pelota.","en":"Two attackers enter through the gate, low, and drive the shield past the ball."},{"es":"El medio scrum saca la pelota. Rotar.","en":"The scrum-half clears the ball. Rotate."}]'::jsonb, 'drill', array['technique']::text[], array['ruck', 'attack']::text[], 11, 4, 12, array['balls', 'shields']::text[], 'controlled', null, 'approved'),
  ('lineout-throw', '{"es":"Lanzamiento de line-out a la marca","en":"Line-out throwing to a target"}'::jsonb, '{"es":"Precisión de lanzamiento a distintas distancias.","en":"Throwing accuracy at different distances."}'::jsonb, '[{"es":"Marcar tres distancias con conos (5, 8 y 11 m).","en":"Mark three distances with cones (5, 8 and 11 m)."},{"es":"El lanzador tira recto a un compañero con los brazos arriba.","en":"The thrower throws straight to a teammate with arms up."},{"es":"Contar aciertos por distancia.","en":"Count hits per distance."}]'::jsonb, 'drill', array['technique']::text[], array['lineout']::text[], 12, 2, 10, array['balls']::text[], 'none', null, 'approved'),
  ('lineout-lift', '{"es":"Levantamiento en line-out","en":"Line-out lifting"}'::jsonb, '{"es":"Técnica de levantamiento con dos soportes y un saltador.","en":"Lifting technique with two lifters and a jumper."}'::jsonb, '[{"es":"Grupos de tres: saltador y dos soportes.","en":"Groups of three: jumper and two lifters."},{"es":"Practicar el agarre y el levantamiento sin pelota, luego con lanzamiento.","en":"Practise the grip and lift without a ball, then with a throw."},{"es":"Bajar siempre al saltador de forma controlada.","en":"Always bring the jumper down in a controlled way."}]'::jsonb, 'drill', array['technique']::text[], array['lineout']::text[], 15, 4, 12, array['balls']::text[], 'none', null, 'approved'),
  ('defensive-line', '{"es":"Línea defensiva: subir juntos","en":"Defensive line: move up together"}'::jsonb, '{"es":"La defensa sube en línea, sin huecos, frente a un ataque que pasa.","en":"The defence moves up as a line, no gaps, against a passing attack."}'::jsonb, '[{"es":"Cuatro defensores frente a cinco atacantes a 10 m.","en":"Four defenders facing five attackers 10 m away."},{"es":"A la señal, la defensa sube junta comunicándose (\"¡adentro!\", \"¡mío!\").","en":"On the call, the defence moves up together communicating (\"inside!\", \"mine!\")."},{"es":"Toque a dos manos. Rotar defensores.","en":"Two-hand touch. Rotate defenders."}]'::jsonb, 'drill', array['technique']::text[], array['defense']::text[], 8, 8, 12, array['balls', 'cones']::text[], 'tag', null, 'approved'),
  ('kicking-basics', '{"es":"Patada: drop y grubber","en":"Kicking: drop and grubber"}'::jsonb, '{"es":"Técnica de patada en parejas, con foco en la precisión.","en":"Kicking technique in pairs, focused on accuracy."}'::jsonb, '[{"es":"Parejas enfrentadas a 15 m.","en":"Pairs facing each other 15 m apart."},{"es":"Alternar drop y grubber al compañero.","en":"Alternate drop kicks and grubbers to your partner."},{"es":"Agregar un cono como objetivo.","en":"Add a cone as a target."}]'::jsonb, 'drill', array['technique']::text[], array['kicking']::text[], 9, 2, 10, array['balls', 'cones']::text[], 'none', null, 'approved'),
  ('scrum-body-position', '{"es":"Scrum: postura 1 contra 1","en":"Scrum: 1 v 1 body position"}'::jsonb, '{"es":"Postura de scrum y encaje sin empuje fuerte, en parejas.","en":"Scrum body position and engagement without hard pushing, in pairs."}'::jsonb, '[{"es":"Trabajar la postura: espalda recta, cabeza arriba, pies al ancho de los hombros.","en":"Work the posture: flat back, head up, feet shoulder-width apart."},{"es":"Encaje lento con el compañero siguiendo las voces del árbitro.","en":"Slow engagement with a partner following the referee calls."},{"es":"Sostener 5 segundos. Sin empuje competitivo.","en":"Hold for 5 seconds. No competitive pushing."}]'::jsonb, 'drill', array['technique']::text[], array['scrum']::text[], 13, 2, 10, '{}'::text[], 'controlled', null, 'approved'),
  ('tag-rugby', '{"es":"Rugby de cintas","en":"Tag rugby"}'::jsonb, '{"es":"Partido reducido sin contacto: se saca la cinta (o se toca) en lugar de tacklear.","en":"Small-sided game without contact: pull the tag (or touch) instead of tackling."}'::jsonb, '[{"es":"Cancha de 30 x 20 m, dos equipos con pecheras.","en":"30 x 20 m pitch, two teams in bibs."},{"es":"Al sacar la cinta, el portador debe pasar en 3 segundos.","en":"When the tag is pulled, the carrier must pass within 3 seconds."},{"es":"Tras 5 cintas sin try, cambio de posesión.","en":"After 5 tags without a try, possession changes."}]'::jsonb, 'game', array['game']::text[], array['attack', 'defense', 'passing', 'evasion']::text[], 6, 6, 20, array['balls', 'cones']::text[], 'tag', null, 'approved'),
  ('end-ball', '{"es":"Pelota al cajón","en":"End ball"}'::jsonb, '{"es":"Se pasa en cualquier dirección y se anota atrapando la pelota en la zona de try.","en":"Pass in any direction and score by catching the ball in the try zone."}'::jsonb, '[{"es":"Cancha de 30 x 20 m con zonas de try de 3 m.","en":"30 x 20 m pitch with 3 m try zones."},{"es":"Quien tiene la pelota no puede correr: sólo pivotea y pasa.","en":"The ball carrier cannot run: only pivot and pass."},{"es":"Se anota atrapando un pase dentro de la zona.","en":"Score by catching a pass inside the zone."}]'::jsonb, 'game', array['game', 'warmup']::text[], array['passing', 'attack']::text[], 6, 6, 15, array['balls', 'cones']::text[], 'none', null, 'approved'),
  ('overload-channel', '{"es":"Superioridad en canal (4 contra 3)","en":"Overload channel (4 v 3)"}'::jsonb, '{"es":"Juego en canal para tomar decisiones con superioridad numérica.","en":"Channel game to make decisions with a numbers advantage."}'::jsonb, '[{"es":"Canal de 20 m de ancho por 25 m de largo.","en":"Channel 20 m wide by 25 m long."},{"es":"Cuatro atacantes contra tres defensores con toque a dos manos.","en":"Four attackers against three defenders, two-hand touch."},{"es":"Variar a 3 contra 2 o 5 contra 4 según el grupo.","en":"Vary to 3 v 2 or 5 v 4 depending on the group."}]'::jsonb, 'game', array['game', 'technique']::text[], array['attack', 'defense', 'passing']::text[], 9, 7, 15, array['balls', 'cones']::text[], 'tag', null, 'approved'),
  ('ruck-game', '{"es":"Juego de ruck","en":"Ruck game"}'::jsonb, '{"es":"Partido reducido donde cada toque obliga a ir al piso y formar un ruck controlado.","en":"Small-sided game where every touch means going to ground and forming a controlled ruck."}'::jsonb, '[{"es":"Cancha de 30 x 25 m, equipos de 4 a 6.","en":"30 x 25 m pitch, teams of 4 to 6."},{"es":"Al ser tocado, el portador cae y presenta; un compañero protege la pelota.","en":"When touched, the carrier goes down and presents; a teammate protects the ball."},{"es":"Contacto controlado: sin limpiezas a velocidad.","en":"Controlled contact: no high-speed clear-outs."}]'::jsonb, 'game', array['game']::text[], array['ruck', 'attack', 'defense']::text[], 11, 8, 15, array['balls', 'cones']::text[], 'controlled', null, 'approved'),
  ('conditioned-match', '{"es":"Partido condicionado","en":"Conditioned match"}'::jsonb, '{"es":"Partido con contacto y una condición según el tema del día (por ejemplo, 3 pases antes del try).","en":"Contact match with a condition tied to the day’s topic (e.g. 3 passes before a try)."}'::jsonb, '[{"es":"Cancha reducida según la cantidad de jugadores.","en":"Reduced pitch based on the number of players."},{"es":"Definir una condición ligada al tema de la sesión.","en":"Set a condition linked to the session topic."},{"es":"Frenar el juego para corregir la técnica de tackle cuando haga falta.","en":"Stop play to correct tackle technique whenever needed."}]'::jsonb, 'game', array['game']::text[], array['tackle', 'ruck', 'attack', 'defense']::text[], 11, 10, 20, array['balls', 'cones']::text[], 'full', null, 'approved'),
  ('stretch-talk', '{"es":"Elongación y charla","en":"Stretch and debrief"}'::jsonb, '{"es":"Vuelta a la calma con elongación y repaso de lo trabajado.","en":"Cool-down with stretching and a review of the session."}'::jsonb, '[{"es":"Ronda de elongación suave.","en":"Gentle stretching circle."},{"es":"Preguntar qué aprendieron y qué les costó.","en":"Ask what they learned and what was hard."},{"es":"Destacar un buen ejemplo del día.","en":"Highlight a good example from the day."}]'::jsonb, 'drill', array['cooldown']::text[], '{}'::text[], 6, 1, 10, '{}'::text[], 'none', null, 'approved'),
  ('accuracy-challenge', '{"es":"Desafío de precisión","en":"Accuracy challenge"}'::jsonb, '{"es":"Pases a un cono objetivo; cada acierto suma punto para el equipo.","en":"Passes at a target cone; every hit scores a point for the team."}'::jsonb, '[{"es":"Dos o tres equipos en fila frente a un cono a 5 m.","en":"Two or three teams in a line facing a cone 5 m away."},{"es":"Cada jugador intenta pegarle al cono con un pase.","en":"Each player tries to hit the cone with a pass."},{"es":"Gana el equipo con más aciertos en 3 minutos.","en":"The team with the most hits in 3 minutes wins."}]'::jsonb, 'game', array['cooldown']::text[], array['passing']::text[], 6, 2, 5, array['balls', 'cones']::text[], 'none', null, 'approved')
